#!/bin/sh
# Run the project's own tests, whatever the stack. The logic lives in tools/testcmd.py:
#   commands.test (pipeline.yaml) > .agents/commands/test.sh (yours) > root markers > sub-folders.
#   sh tools/projecttest.sh list   shows what would run and why, and runs nothing.
# Do not edit this file to customize: it is kit-managed and an update overwrites it. Use the two above.
cd "$(dirname "$0")/.."
exec python3 tools/testcmd.py "${1:-run}"
